import{_ as o,c as n,o as i,ae as s}from"./chunks/framework.Bi6zybwU.js";const h=JSON.parse('{"title":"Column Responsive Breakpoints","description":"Column Responsive Breakpoints","frontmatter":{"title":"Column Responsive Breakpoints","description":"Column Responsive Breakpoints"},"headers":[],"relativePath":"guide/responsive-design/column-responsive-breakpoints.md","filePath":"guide/responsive-design/column-responsive-breakpoints.md"}'),t={name:"guide/responsive-design/column-responsive-breakpoints.md"};function a(l,e,r,p,c,d){return i(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="column-responsive-breakpoints" tabindex="-1">Column Responsive Breakpoints <a class="header-anchor" href="#column-responsive-breakpoints" aria-label="Permalink to &quot;Column Responsive Breakpoints&quot;">​</a></h1><p>Ninja Tables has a useful feature that allows users to display data in a table utilizing 6 separate responsive breakpoints. The device widths are all configured to the exact values appropriate for your goal. This feature helps to ensure that your website&#39;s tables are responsive. Here is a brief instruction on configuring Ninja Tables&#39; Responsive Breakpoints. So let&#39;s go over how this operates -</p><ul><li>First, go to the <strong>Table Configuration</strong> tab and click on the <strong>Edit</strong> icon (Pencil icon) on the right side of the column to modify your desired column to configure the responsive breakpoints.</li><li>You will notice a drop-down containing six options in the Responsive Breakpoint field. <img src="https://ninjatables.com/wp-content/uploads/2022/09/Column-Responsive-Breakpoint-1-1-scaled.webp" alt="Column Responsive Breakpoint "> Let&#39;s talk about the six responsive breakpoints in detail below -</li><li><strong>Always show on all devices</strong>*: *This lets the column be displayed on every device.</li><li><strong>Hidden On Desktop</strong>*: *The column will be displayed on mobiles &amp; tablets except for desktop devices.</li><li><strong>Initial hidden mobile</strong>*: *This allows you to view the columns on all devices other than mobile devices. The column hides beneath the plus(+) icon in the mobile view. So when a user clicks this icon, the hidden column data will be shown. <img src="https://ninjatables.com/wp-content/uploads/2023/02/Column-Responsive-Breakdown-1.png" alt="mobile responsive breakpoint"></li><li><strong>Initial hidden Mobile and tab</strong>*: *This lets you view the columns on all devices other than mobile &amp; tab devices. The column will be hidden under a plus(+) icon on mobile and tab devices. The data from the column is shown when this icon is clicked.</li><li>**Initial hidden Mobile, Tab, and all Regular Computers: **After selecting this option, the plus(+) icon will hide the column data on all kinds of devices. Like the previous options, users must click the plus(+) icon to display the data.</li><li><strong>Totally hidden on all devices</strong>*: *This option allows you to keep the columns hidden on all devices. You can choose any of the choices that best fit your needs. When you want to show certain data on limited devices, make sure you select the suitable configuration from the <strong>Responsive</strong> <strong>Breakpoint</strong> segment.</li><li><strong>Hide Empty Items on responsive breakdown:</strong> If You enable this, then the empty **cell items **of a column, then the responsive breakpoint will not show on this column.</li><li><strong>Hide Labels on responsive breakdown:</strong> If You enable this, then column headings will not show in a responsive drawer / Stackable View. <img src="https://ninjatables.com/wp-content/uploads/2022/09/Column-Responsive-Breakpoint-2-1-scaled.webp" alt="Column Responsive Breakpoint "> Configuring responsive breakpoints in Ninja Tables can make your data tables adjust to all screen sizes. And once you hide a column, it still can be visible when you click the &quot;+&quot; sign. Try using this feature when you don&#39;t want to show a column that carries somewhat irrelevant data.</li></ul>',3)])])}const m=o(t,[["render",a]]);export{h as __pageData,m as default};
